+  inset: 0;
+  display: grid;
+  place-items: center;
+  mix-blend-mode: difference;
+}
+.loader__word {
+  font-size: clamp(64px, 16vw, 260px);
+  font-weight: 300;
+  font-style: italic;
+  letter-spacing: -0.03em;
+  line-height: 1;
