+}
+
+.meridian {
+  position: fixed;
+  right: calc(var(--pad) * 0.7);
+  top: 50%;
+  z-index: 60;
+  transform: translateY(-50%);
+  display: flex;
+  flex-direction: column;
+  gap: 18px;
+  mix-blend-mode: difference;
+  color: var(--bone);
+}
+.meridian::before {
+  content: '';
+  position: absolute;
+  right: 6px;
+  top: -40px;
+  bottom: -40px;
+  width: 1px;
+  background: linear-gradient(transparent, rgba(241, 232, 214, 0.45), transparent);
+}
+.meridian a {
+  position: relative;
+  display: flex;
+  align-items: center;
+  justify-content: flex-end;
+  gap: 12px;
+  font-size: 15px;
+  opacity: 0.45;
+  transition: opacity 0.4s;
+}
+.meridian a::after {
+  content: '';
