+}
+.meridian a.is-active::after {
+  background: var(--bone);
+  transform: scale(0.7);
+}
+.meridian a:hover span,
+.meridian a.is-active span {
+  opacity: 1;
+  transform: none;
+}
+
+/* ———————————————————————— hero */
+
+.hero {
+  position: relative;
+  height: 100vh;
+  height: 100svh;
+  min-height: 560px;
+  overflow: hidden;
+  isolation: isolate;
