+}
+.doctrine__sign {
+  display: flex;
+  align-items: center;
+  gap: 24px;
+  margin-top: 56px;
+  color: var(--saffron);
+}
+.doctrine__sign svg {
+  width: 180px;
+  height: auto;
+}
+
+/* ———————————————————————— arch */
+
+.arch {
+  position: relative;
+  background: var(--ink);
+}
+.arch__pin {
+  position: relative;
+  height: 100vh;
+  height: 100svh;
+  overflow: hidden;
+  display: grid;
+  place-items: center;
+}
+.arch__window {
+  position: absolute;
+  left: 50%;
+  top: 50%;
+  width: 300px;
+  height: 440px;
+  transform: translate(-50%, -50%);
+  overflow: hidden;
+  border-radius: 150px 150px 0 0;
+  z-index: 2;
+  box-shadow: 0 0 0 1px rgba(242, 165, 30, 0.35);
+}
+.arch__window::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(180deg, transparent 50%, rgba(12, 24, 29, 0.75));
+  opacity: var(--shade, 0);
+}
+.arch__window img {
+  position: absolute;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  object-position: 35% 40%;
+  transform: scale(1.5);
+  transform-origin: 30% 40%;
+}
+.arch__side {
+  position: absolute;
+  top: 50%;
+  display: flex;
+  flex-direction: column;
+  gap: 14px;
+  transform: translateY(-50%);
+  z-index: 1;
+}
+.arch__side b {
+  font-weight: 300;
+  font-style: italic;
+  font-size: clamp(64px, 12vw, 210px);
+  line-height: 0.8;
+  letter-spacing: -0.04em;
+}
+.arch__side--l {
+  right: calc(50% + 170px);
+  align-items: flex-end;
+  text-align: right;
+}
+.arch__side--r {
+  left: calc(50% + 170px);
+}
+.arch__side .mono {
+  color: var(--saffron);
+}
+.arch__caption {
+  position: absolute;
+  left: var(--pad);
+  bottom: var(--pad);
+  z-index: 3;
+  max-width: 560px;
+  opacity: 0;
+}
