+    radial-gradient(60vw 40vw at 85% 0%, rgba(239, 134, 118, 0.18), transparent 70%),
+    radial-gradient(50vw 40vw at 0% 100%, rgba(242, 165, 30, 0.16), transparent 70%);
+}
+.vials .label {
+  color: #b5521f;
+}
+.vials__head {
+  position: relative;
+  display: grid;
