+    linear-gradient(90deg, rgba(255, 255, 255, 0.4) 0, transparent 9%, transparent 70%, rgba(255, 255, 255, 0.22) 84%, transparent 92%),
+    linear-gradient(180deg, rgba(255, 255, 255, 0.28), transparent 18%);
