+.immersion[hidden] {
+  display: none;
+}
+.immersion__media {
+  position: absolute;
+  inset: 0;
+  overflow: hidden;
+}
+.immersion__media img {
+  position: absolute;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+}
+.immersion__shade {
+  position: absolute;
+  inset: 0;
+  background:
+    linear-gradient(90deg, rgba(12, 24, 29, 0.88) 0%, rgba(12, 24, 29, 0.55) 40%, transparent 70%),
+    linear-gradient(0deg, rgba(12, 24, 29, 0.6), transparent 40%);
