+  font-style: italic;
+  line-height: 0.85;
+  letter-spacing: -0.035em;
+  margin: 14px 0 22px;
+}
+.immersion__story {
+  font-size: clamp(20px, 1.8vw, 27px);
+  line-height: 1.2;
+  max-width: 500px;
+}
+.immersion__notes {
