+
+/* ———————————————————————— slices */
+
+.slices {
+  position: relative;
+  background: var(--ink);
+}
+.slices__pin {
+  position: relative;
+  height: 100vh;
+  height: 100svh;
+  overflow: hidden;
+}
+.slices__stage {
+  position: absolute;
+  inset: 0;
+}
+.slice {
+  position: absolute;
+  top: 0;
+  bottom: 0;
+  overflow: hidden;
+  will-change: transform;
+}
+.slice img {
+  position: absolute;
+  top: 0;
+  height: 100%;
+  max-width: none;
+  object-fit: cover;
+  object-position: 55% 50%;
+}
+.slices__shade {
+  position: absolute;
+  inset: 0;
