+  font-weight: 300;
+  line-height: 0.82;
+  letter-spacing: -0.04em;
+  margin: 16px 0 22px;
+}
+.slices__text h2 em {
+  color: var(--saffron);
+}
+.slices__text p {
+  font-size: clamp(20px, 1.9vw, 30px);
